     1→import { defineConfig } from "tsup";
     2→import { readFileSync } from "fs";
     3→import { join } from "path";
     4→
     5→export default defineConfig({
     6→	entry: ["src/index.ts"],
     7→	format: ["iife"],
     8→	outDir: "dist",
     9→	globalName: "ClaudeApp",
    10→	minify: true,
    11→	sourcemap: "inline",
    12→	clean: false, // Don't clean CSS file
    13→	noExternal: ["lit", "marked", "highlight.js"],
    14→	target: "es2022",
    15→	esbuildOptions: (options) => {
    16→		options.banner = {
    17→			js: "/* Claude Tools Frontend Bundle */",
    18→		};
    19→
    20→		// Source maps enabled for debugging
    21→
    22→		// Inject CSS content - read dynamically on each build
    23→		options.define = {
    24→			...options.define,
    25→			get __CSS_CONTENT__() {
    26→				try {
    27→					return JSON.stringify(readFileSync(join(process.cwd(), "dist/styles.css"), "utf8"));
    28→				} catch {
    29→					return JSON.stringify("");
    30→				}
    31→			},
    32→		};
    33→	},
    34→});
